    36→  Copy,
    37→  ExternalLink,
    38→  Loader2,
    39→  Timer,
    40→  Wallet,
    41→} from "lucide-react";
    42→import { upfetch } from "@/lib/up-fetch";
    43→import { logger } from "@/lib/logger";
    44→import { TestnetBadge } from "./testnet-badge";
    45→import { SiteConfig } from "@/site-config";
    46→import { TestPaymentSuccessDialog } from "./test-payment-success-dialog";
    47→import {
    48→  LayoutHeader,
    49→  LayoutTitle,
    50→  LayoutDescription,
    51→  LayoutContent,
    52→} from "@/features/page/layout";
    53→
    54→type CheckoutFormProps = {
    55→  plan: MyCryptoPilotPlanName;
    56→  isTestnet?: boolean;
    57→};
    58→
    59→type GeneratedAddresses = {
    60→  base: {
    61→    id: string;
    62→    address: string;
    63→    network: "BASE";
    64→  };
    65→  tron: {
    66→    id: string;
    67→    address: string;
    68→    network: "TRON";
    69→  };
    70→};
    71→
    72→type PaymentStatus = "pending" | "confirmed" | "expired";
    73→
    74→export const CheckoutForm = ({
    75→  plan,
    76→  isTestnet = false,
    77→}: CheckoutFormProps) => {
    78→  const router = useRouter();
    79→  const planData = MYCRYPTOPILOT_PLANS.find((p) => p.name === plan);
    80→
    81→  if (!planData) {
    82→    throw new Error(`Plan ${plan} not found`);
    83→  }
    84→
    85→  const [addresses, setAddresses] = useState<GeneratedAddresses | null>(null);
    86→  const [expiresAt, setExpiresAt] = useState<Date | null>(null);
    87→  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus>("pending");
    88→  const [qrCodes, setQrCodes] = useState<{
    89→    base: string;
    90→    tron: string;
    91→  } | null>(null);
    92→  const [showTestSuccessDialog, setShowTestSuccessDialog] = useState(false);
    93→
    94→  // Generate crypto addresses on mount
    95→  const generateMutation = useMutation({
    96→    mutationFn: async () => {
    97→      const result = await generateAddressAction({
    98→        plan: plan as "test" | "pro" | "ultra",
    99→      });
   100→
   101→      if (!isActionSuccessful(result)) {
   102→        throw new Error(result.serverError ?? "Failed to generate addresses");
   103→      }
   104→
   105→      return result.data;
   106→    },
   107→    onSuccess: async (data) => {
   108→      setAddresses(data.addresses);
   109→      setExpiresAt(new Date(data.expiresAt));
   110→
   111→      // Generate QR codes
   112→      try {
   113→        const [baseQR, tronQR] = await Promise.all([
   114→          QRCode.toDataURL(data.addresses.base.address, { width: 256 }),
   115→          QRCode.toDataURL(data.addresses.tron.address, { width: 256 }),
   116→        ]);
   117→        setQrCodes({ base: baseQR, tron: tronQR });
   118→      } catch (error) {
   119→        logger.error("Failed to generate QR codes", { error });
   120→        toast.error("Failed to generate QR codes");
   121→      }
   122→    },
   123→    onError: (error) => {
