   148→          schema: z.object({
   149→            confirmed: z.boolean(),
   150→            pending: z.boolean().optional(),
   151→            plan: z.string().optional(),
   152→            daysGranted: z.number().optional(),
   153→            periodEnd: z.string().optional(),
   154→            txHash: z.string().optional(),
   155→            error: z.string().optional(),
   156→          }),
   157→        });
   158→
   159→        if (result.confirmed) {
